#
# Checks that each library crate's committed public API listing matches the
# code, or regenerates the listings with --update.
#
# The listings are generated by cargo-public-api from rustdoc JSON, so they
# are the mechanical record of every public item and its signature
# (quality-criteria Q2). `specs/<crate>/public-api.md` describes the API in
# prose; the listing is what keeps it honest.
#
# Usage:
#   scripts/check_public_api.sh            # check; exits 1 and prints a diff on drift
#   scripts/check_public_api.sh --update   # rewrite the listings for this OS
#
# A crate's listing is `specs/<crate>/public-api.txt`. When a crate's API
# differs by platform (openjd-sessions exposes Windows-only and Unix-only
# items), the OS-specific `specs/<crate>/public-api.<os>.txt` is used instead
# where it exists, with <os> one of linux, macos, windows. `--update` writes
# to whichever file the check would read, so regenerate an OS-specific
# listing on that OS. CI runs the check on Linux and Windows and uploads the
# regenerated listings when it fails.
#
# Requires cargo-public-api and the nightly toolchain below. They are pinned
# together because cargo-public-api reads rustdoc's unstable JSON format:
#   rustup toolchain install nightly-2026-07-09 --profile minimal
#   cargo install cargo-public-api --locked --version 0.52.0

set -euo pipefail

# Keep in sync with the `public-api` job in .github/workflows/ci.yml.
TOOLCHAIN="nightly-2026-07-09"

# Library crates with a public API listing. openjd-cli has no library target,
# and openjd-for-js's API is its JavaScript surface, not its Rust one.
CRATES=(expr model sessions snapshots)

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
cd "$REPO_ROOT"

mode=check
case "${1:-}" in
    "") ;;
    --update) mode=update ;;
    *)
        echo "usage: $0 [--update]" >&2
        exit 2
        ;;
esac

case "$(uname -s)" in
    Linux*) os=linux ;;
    Darwin*) os=macos ;;
    MINGW* | MSYS* | CYGWIN*) os=windows ;;
    *)
        echo "unsupported OS: $(uname -s)" >&2
        exit 2
        ;;
esac

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

status=0
for crate in "${CRATES[@]}"; do
    listing="specs/$crate/public-api.txt"
    if [[ -f "specs/$crate/public-api.$os.txt" ]]; then
        listing="specs/$crate/public-api.$os.txt"
    fi

    # -ss omits blanket impls (`impl<T> From<T> for T`) and auto-trait impls
    # (Send, Sync, Unpin), which would otherwise be a large share of every
    # listing. The cost is that a type silently losing Send or Sync does not
    # show up here; cargo-semver-checks in the release workflow catches that.
    # Derived impls (Clone, Debug, ...) are kept: removing one is an API
    # change. `tr` drops the carriage returns a Windows pipe can add.
    cargo "+$TOOLCHAIN" public-api -p "openjd-$crate" -ss --color=never |
        tr -d '\r' >"$tmp/$crate.txt"

    if [[ $mode == update ]]; then
        cp "$tmp/$crate.txt" "$listing"
        echo "Updated $listing"
    elif ! diff -u "$listing" "$tmp/$crate.txt"; then
        echo "error: $listing does not match the public API of openjd-$crate." >&2
        status=1
    fi
done

if [[ $status -ne 0 ]]; then
    echo >&2
    echo "Run scripts/check_public_api.sh --update, review the diff, and update" >&2
    echo "specs/<crate>/public-api.md to describe any added or changed items." >&2
fi
exit "$status"
